package site.leawsic.chess.config;
import java.util.*;
public final class GomokuAi {private static final int[][] DIRECTIONS={{1,0},{0,1},{1,1},{1,-1}};private static final int CANDIDATE_LIMIT=24;private GomokuAi(){}
 public static Move chooseMove(int[][]b,int ai){int op=other(ai);List<Move>wins=winningMoves(b,ai);if(!wins.isEmpty())return wins.get(0);List<Move>opWins=winningMoves(b,op);if(opWins.size()==1){Move m=opWins.get(0);return new Move(m.x(),m.y(),ai);}List<ScoredMove>cs=candidates(b,ai,CANDIDATE_LIMIT);if(cs.isEmpty())return null;ScoredMove best=null;int bestScore=Integer.MIN_VALUE;for(ScoredMove c:cs){int x=c.move.x(),y=c.move.y();b[y][x]=ai;int score;List<Move> replies=winningMoves(b,op);if(!replies.isEmpty())score=-8_000_000-replies.size()*100_000+attackValue(b,x,y,ai);else{int worst=0;for(ScoredMove r:candidates(b,op,14)){b[r.move.y()][r.move.x()]=op;int rs=attackValue(b,r.move.x(),r.move.y(),op)-bestFollowUp(b,ai);b[r.move.y()][r.move.x()]=0;worst=Math.max(worst,rs);}int forcing=winningMoves(b,ai).size(),bonus=forcing>=2?4_000_000:forcing==1?250_000:0;score=attackValue(b,x,y,ai)*4+bonus-worst;}b[y][x]=0;if(score>bestScore){bestScore=score;best=c;}}return best==null?null:best.move;}
 private static int bestFollowUp(int[][]b,int p){List<ScoredMove>m=candidates(b,p,6);if(m.isEmpty())return 0;ScoredMove best=m.get(0);b[best.move.y()][best.move.x()]=p;int s=attackValue(b,best.move.x(),best.move.y(),p);b[best.move.y()][best.move.x()]=0;return s;}private static List<ScoredMove> candidates(int[][]b,int p,int limit){int op=other(p),cx=b[0].length/2,cy=b.length/2;boolean empty=true;List<ScoredMove>m=new ArrayList<>();for(int y=0;y<b.length;y++)for(int x=0;x<b[0].length;x++){if(b[y][x]!=0){empty=false;continue;}if(!hasNeighbor(b,x,y)&&!(x==cx&&y==cy))continue;int score=scorePoint(b,x,y,p)*6+scorePoint(b,x,y,op)*4-Math.abs(x-cx)-Math.abs(y-cy);m.add(new ScoredMove(new Move(x,y,p),score));}if(empty)return List.of(new ScoredMove(new Move(cx,cy,p),1));m.sort(Comparator.comparingInt(ScoredMove::score).reversed());return m.size()>limit?new ArrayList<>(m.subList(0,limit)):m;}private static boolean hasNeighbor(int[][]b,int x,int y){for(int dy=-2;dy<=2;dy++)for(int dx=-2;dx<=2;dx++){int nx=x+dx,ny=y+dy;if(ny>=0&&ny<b.length&&nx>=0&&nx<b[0].length&&b[ny][nx]!=0)return true;}return false;}private static int scorePoint(int[][]b,int x,int y,int p){int s=0;for(int[]d:DIRECTIONS){int f=count(b,x,y,d[0],d[1],p),back=count(b,x,y,-d[0],-d[1],p),stones=f+back+1,open=isOpen(b,x+(f+1)*d[0],y+(f+1)*d[1])?1:0;open+=isOpen(b,x-(back+1)*d[0],y-(back+1)*d[1])?1:0;s+=lineScore(stones,open);}return s;}private static int threatBonus(int[][]b,int x,int y,int p){int fours=0,threes=0;for(int[]d:DIRECTIONS){int f=count(b,x,y,d[0],d[1],p),back=count(b,x,y,-d[0],-d[1],p),stones=f+back+1,open=isOpen(b,x+(f+1)*d[0],y+(f+1)*d[1])?1:0;open+=isOpen(b,x-(back+1)*d[0],y-(back+1)*d[1])?1:0;if(stones==4&&open>0)fours++;if(stones==3&&open==2)threes++;}return fours>=2?2_500_000:fours==1?450_000:threes>=2?180_000:threes==1?12_000:0;}private static int attackValue(int[][]b,int x,int y,int p){return scorePoint(b,x,y,p)+threatBonus(b,x,y,p);}private static List<Move> winningMoves(int[][]b,int p){List<Move>m=new ArrayList<>();for(int y=0;y<b.length;y++)for(int x=0;x<b[0].length;x++)if(b[y][x]==0){b[y][x]=p;if(isWin(b,x,y,p))m.add(new Move(x,y,p));b[y][x]=0;}return m;}private static boolean isWin(int[][]b,int x,int y,int p){for(int[]d:DIRECTIONS)if(1+count(b,x,y,d[0],d[1],p)+count(b,x,y,-d[0],-d[1],p)>=5)return true;return false;}private static int count(int[][]b,int x,int y,int dx,int dy,int p){int n=0;for(x+=dx,y+=dy;y>=0&&y<b.length&&x>=0&&x<b[0].length&&b[y][x]==p;x+=dx,y+=dy)n++;return n;}private static boolean isOpen(int[][]b,int x,int y){return y>=0&&y<b.length&&x>=0&&x<b[0].length&&b[y][x]==0;}private static int lineScore(int s,int o){if(s>=5)return 2_000_000;if(s==4)return o==2?300_000:o==1?40_000:0;if(s==3)return o==2?15_000:o==1?1_500:0;if(s==2)return o==2?600:o==1?80:0;return o==2?15:0;}private static int other(int p){return p==1?2:1;}private record ScoredMove(Move move,int score){}}
